CREATE OR REPLACE FUNCTION public.validate_applicant_program() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.program NOT IN ('CNA','HHA') THEN RAISE EXCEPTION 'Invalid program'; END IF; IF NEW.program = 'HHA' AND (NEW.selected_cohort_date IS NOT NULL OR NEW.orientation_date IS NOT NULL OR NEW.cohort_id IS NOT NULL OR NEW.preferred_schedule IS NULL OR NEW.preferred_schedule NOT IN ('Daytime','Weekend','Either')) THEN RAISE EXCEPTION 'HHA is a priority list without cohort or orientation dates'; END IF; RETURN NEW; END; $$;